from typing import List, Dict, Any

def solve(instance: Dict[str, Any]) -> bool:
    u = instance["universe_size"]
    sets = instance["sets"]
    n_sets = len(sets)
    # Preprocess each set as a bitmask for speed
    masks = []
    for s in sets:
        mask = 0
        for e in s:
            mask |= 1 << e
        masks.append(mask)
    full_mask = (1 << u) - 1
    # Enumerate subsets
    for subset in range(1 << n_sets):
        combined = 0
        ok = True
        for i in range(n_sets):
            if (subset >> i) & 1:
                if combined & masks[i]:
                    ok = False
                    break
                combined |= masks[i]
        if ok and combined == full_mask:
            return True
    return False
EOF"}

